<script lang="ts" module>

	const makeSpreads = (pages: ReaderPage[], offset: number = 0): Array<ReaderPage[]> => {
		const result: Array<ReaderPage[]> = [];
		for (let i = 0; i < pages.length; i++) {
			const current = pages[i];

			// If it's a wide (landscape) page, show it as a single spread
			if (i < offset || current.data.dimensions[0] > current.data.dimensions[1]) {
				result.push([current]);
				continue;
			}

			// If next page exists and both are not wide, make a double spread
			const next = pages[i + 1];
			if (next?.data.dimensions[0] <= next?.data.dimensions[1]) {
				result.push([current, next]);
				i++; // Skip the next page since it's already paired
			} else {
				// Otherwise, single page
				result.push([current]);
			}
		}
		return result;
	};
</script>

<!-- svelte-ignore state_referenced_locally -->
<script lang="ts">
	import { replaceState } from "$app/navigation";
	import { page } from "$app/state";
	import { Constants } from "$lib";
	import API from "$lib/API";
	import { dataSaver, mangaPrefs, webtoonPrefs } from "$lib/stores";
	import { StatusCodes } from "http-status-codes";
	import { onDestroy, onMount, tick, type Snippet } from "svelte";
	import { writable } from "svelte/store";
	import { setReader } from "./context.svelte";
	import Analytics from "./reader-analytics.svelte";
	import History from "./reader-history.svelte";
	import Keyboard from "./reader-keyboard-listener.svelte";
	import Queue from "./reader-queue.svelte";
	import Scroll from "./reader-scroll-listener.svelte";

	const { chapter, children }: { chapter: Chapter; children: Snippet } = $props();
	let aggregated = $state<ChapterAggregateResponse>();
	let aggregateGeneration = 0, aggregateDisposed = false;
	onDestroy(() => { aggregateDisposed = true; aggregateGeneration++; aggregated = undefined; });
	const reader = setReader({
		prefs:
			chapter.relationships.manga.language != "ja" ||
			chapter.relationships.manga.relationships.tags?.some(
				e => e.group === Constants.Tag.Group.Format && e.name === "Long Strip"
			)
				? webtoonPrefs
				: mangaPrefs,
		chapter: chapter,
		aggregated: () => aggregated
	});
	const readerPrefs = $derived(reader.prefs);
	onDestroy(() => reader.pages.forEach(page => { if (page.blob) URL.revokeObjectURL(page.blob); }));

	onMount(() => {
		const generation = ++aggregateGeneration;
		const alive = () => !aggregateDisposed && generation === aggregateGeneration;
		void (async () => {
			await tick(); if (!alive()) return;
			if (reader.isViewingLastPage) {
				const lastIndex = Math.max(reader.pages.length - 1, 0);
				reader.currentPage = reader.pages[lastIndex];
				replaceState(`/chapter/${chapter.id}/${lastIndex + 1}`, { ...page.state, page: lastIndex + 1 });
			} else if (!page.params.page) replaceState(`/chapter/${chapter.id}/1`, { ...page.state, page: 1 });
			const mangaId = chapter.relationships.manga.id, chapterId = chapter.id;
			const q = new URLSearchParams(); q.set("tlang", chapter.language);
			const contextKey = JSON.stringify([mangaId, [...q.entries()]]);
			aggregated = undefined;
			const res = await API.Chapter.Aggregate(mangaId, q);
			if (!alive() || chapter.id !== chapterId || JSON.stringify([chapter.relationships.manga.id, [["tlang", chapter.language]]]) !== contextKey) return;
			// Every mounted reader rechecks current authority; failures/hidden results are never cached.
			aggregated = res?.status === StatusCodes.OK && res.body ? res.body : undefined;
		})().catch(error => { if (alive()) { aggregated = undefined; console.error(error); } });
	});

	let previousOffset: number;
	let previousDataSaver: boolean;
	$effect(() => {
		let isPreviousDataSaverChanged = previousDataSaver !== $dataSaver;
		if (isPreviousDataSaverChanged) previousDataSaver = $dataSaver;
		let isPreviousOffsetChanged = previousOffset !== $readerPrefs.offset;
		if (isPreviousOffsetChanged) previousOffset = $readerPrefs.offset;

		if (isPreviousDataSaverChanged) {
			reader.pages.forEach(page => { if (page.blob) URL.revokeObjectURL(page.blob); });
			reader.key++;
			reader.pages = (($dataSaver && chapter.data_optimized ? chapter.data_optimized : chapter.data) ?? [])?.map(
				(e, i) => ({
					data: e,
					index: i,
					ref: writable<HTMLDivElement | undefined>()
				})
			);
			const requestedPage = Number((page.state as any).page ?? page.params.page ?? 1);
			const safePage = Number.isFinite(requestedPage) ? Math.trunc(requestedPage) : 1;
			reader.currentPage = reader.pages[Math.min(Math.max(safePage, 1), reader.pages.length) - 1];
		}
		if (isPreviousOffsetChanged || isPreviousDataSaverChanged) {
			reader.spreads = makeSpreads(reader.pages, $readerPrefs.offset);
		}
	});
</script>

{#key reader.key}
	<Queue />
{/key}

<Scroll />
<Keyboard />

{#if reader.pages.length}
	<Analytics />
	<History />
{/if}

{@render children()}
